(function(){
  'use strict';
  function hexToBytes(s){
    var t=String(s||'').replace(/0x/gi,' ').replace(/[^0-9a-fA-F]/g,'');
    if(t.length%2) t=t.slice(0,-1);
    var o=new Uint8Array(t.length/2);
    for(var i=0;i<o.length;i++) o[i]=parseInt(t.substr(i*2,2),16);
    return o;
  }
  function b64ToBytes(s){
    var t=String(s||'').replace(/-----[^-]+-----/g,'').replace(/[^A-Za-z0-9+/=]/g,'');
    var A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    var out=[],buf=0,bits=0;
    for(var i=0;i<t.length;i++){
      if(t[i]==='=') break;
      var v=A.indexOf(t[i]); if(v<0) continue;
      buf=(buf<<6)|v; bits+=6;
      if(bits>=8){ bits-=8; out.push((buf>>bits)&255); }
    }
    return new Uint8Array(out);
  }
  function toHex(b,sep){ var o=[]; for(var i=0;i<b.length;i++){var x=b[i].toString(16); o.push(x.length<2?'0'+x:x);} return o.join(sep||''); }

  var UNIV={1:'BOOLEAN',2:'INTEGER',3:'BIT STRING',4:'OCTET STRING',5:'NULL',6:'OBJECT IDENTIFIER',
            7:'ObjectDescriptor',10:'ENUMERATED',12:'UTF8String',13:'RELATIVE-OID',16:'SEQUENCE',
            17:'SET',18:'NumericString',19:'PrintableString',20:'T61String',22:'IA5String',
            23:'UTCTime',24:'GeneralizedTime',26:'VisibleString',27:'GeneralString',30:'BMPString'};
  var CLS=['UNIVERSAL','APPLICATION','CONTEXT','PRIVATE'];
  var OIDS={
    '1.2.840.113549.1.1.1':'rsaEncryption','1.2.840.113549.1.1.11':'sha256WithRSAEncryption',
    '1.2.840.113549.1.1.5':'sha1WithRSAEncryption','1.2.840.113549.1.1.12':'sha384WithRSAEncryption',
    '1.2.840.113549.1.1.13':'sha512WithRSAEncryption','1.2.840.10045.2.1':'id-ecPublicKey',
    '1.2.840.10045.4.3.2':'ecdsa-with-SHA256','1.2.840.10045.3.1.7':'prime256v1 (P-256)',
    '1.3.132.0.34':'secp384r1 (P-384)','1.3.132.0.35':'secp521r1 (P-521)',
    '1.3.101.112':'Ed25519','1.3.101.110':'X25519',
    '2.5.4.3':'commonName (CN)','2.5.4.6':'countryName (C)','2.5.4.7':'localityName (L)',
    '2.5.4.8':'stateOrProvinceName (ST)','2.5.4.10':'organizationName (O)',
    '2.5.4.11':'organizationalUnitName (OU)','2.5.29.14':'subjectKeyIdentifier',
    '2.5.29.15':'keyUsage','2.5.29.17':'subjectAltName','2.5.29.19':'basicConstraints',
    '2.5.29.35':'authorityKeyIdentifier','2.5.29.37':'extKeyUsage',
    '2.16.840.1.101.3.4.2.1':'sha-256','2.16.840.1.101.3.4.2.2':'sha-384','2.16.840.1.101.3.4.2.3':'sha-512'
  };

  function decodeOid(b){
    if(!b.length) return '';
    // 先按 base-128 续位规则切出所有子标识符
    var subs=[], v=0, started=false;
    for(var i=0;i<b.length;i++){
      if(!started && b[i]===128) return null;   // 子标识符前导 0x80，非最短编码
      v = v*128 + (b[i]&127);
      started=true;
      if(!(b[i]&128)){ subs.push(v); v=0; started=false; }
    }
    if(started) return null;   // 未终止的子标识符
    // 首个子标识符编码了 X*40+Y；X>=2 时 Y 无上限
    var first=subs.shift(), parts;
    if(first<40) parts=[0, first];
    else if(first<80) parts=[1, first-40];
    else parts=[2, first-80];
    return parts.concat(subs).join('.');
  }
  function decodeInt(b){
    if(!b.length) return '0';
    if(b.length<=6){
      var n=0, neg=(b[0]&128)!==0;
      for(var i=0;i<b.length;i++) n=n*256+b[i];
      if(neg) n -= Math.pow(2, b.length*8);
      return String(n);
    }
    return '0x'+toHex(b);
  }
  function ascii(b){ var s=''; for(var i=0;i<b.length;i++) s+=String.fromCharCode(b[i]); return s; }

  function parse(input){
    var b = (input instanceof Uint8Array) ? input
          : (/^[\s0-9a-fA-F,x]*$/.test(String(input)) ? hexToBytes(input) : b64ToBytes(input));
    if(!b.length) return {value:null, error:'输入为空'};
    var pos=0, warns=[];

    function one(depth){
      if(depth>32) throw new Error('嵌套超过 32 层（偏移 '+pos+'）');
      var start=pos;
      if(pos>=b.length) throw new Error('数据在偏移 '+pos+' 处意外结束');
      var id=b[pos++], cls=(id>>6)&3, cons=(id&32)!==0, tag=id&31;
      if(tag===31){
        tag=0;
        do{
          if(pos>=b.length) throw new Error('高位 tag 未终止（偏移 '+pos+'）');
          tag=tag*128+(b[pos]&127);
        } while(b[pos++]&128);
      }
      if(pos>=b.length) throw new Error('缺少长度字节（偏移 '+pos+'）');
      var lb=b[pos++], len;
      if(lb===128){ throw new Error('检测到 BER 不定长（0x80），DER 不允许（偏移 '+(pos-1)+'）'); }
      if(lb&128){
        var nb=lb&127;
        if(nb>4) throw new Error('长度字段过长（'+nb+' 字节，偏移 '+(pos-1)+'）');
        if(pos+nb>b.length) throw new Error('长度字段被截断（偏移 '+pos+'）');
        len=0; for(var i=0;i<nb;i++) len=len*256+b[pos++];
        if(len<128) warns.push('偏移 '+start+'：长度 '+len+' 用了长格式，DER 要求最短编码');
      } else len=lb;
      if(pos+len>b.length) throw new Error('内容长度 '+len+' 超出剩余 '+(b.length-pos)+' 字节（偏移 '+pos+'）');
      var content=b.subarray(pos,pos+len), end=pos+len;

      var name = cls===0 ? (UNIV[tag]||('[UNIVERSAL '+tag+']')) : ('['+(cls===2?'':CLS[cls]+' ')+tag+']');
      var node={offset:start, header:pos-start, length:len, tag:tag, cls:CLS[cls],
                constructed:cons, name:name, children:[], value:null};

      if(cons){
        var save=pos;
        while(pos<end) node.children.push(one(depth+1));
        if(pos!==end){ pos=save; throw new Error('子结构长度与父容器不符（偏移 '+start+'）'); }
      } else {
        pos=end;
        if(cls===0){
          if(tag===1) node.value = content[0]===0 ? 'FALSE' : (content[0]===255 ? 'TRUE' : 'TRUE (非 DER: 0x'+toHex(content)+')');
          else if(tag===2 || tag===10) node.value = decodeInt(content);
          else if(tag===5) node.value = len===0 ? 'NULL' : 'NULL (长度应为 0)';
          else if(tag===6){ var o=decodeOid(content); node.value = o===null ? '(非法 OID 编码)' : (o + (OIDS[o]?('  — '+OIDS[o]):'')); node.oid=o; }
          else if(tag===3){
            var unused = content.length ? content[0] : 0;
            node.value = '未用位 '+unused+'，'+(content.length-1)+' 字节: '+toHex(content.subarray(1,Math.min(content.length,17)))+(content.length>17?'…':'');
          }
          else if(tag===12||tag===19||tag===22||tag===26||tag===27||tag===18) node.value = ascii(content);
          else if(tag===23||tag===24) node.value = ascii(content);
          else node.value = toHex(content.subarray(0,Math.min(len,24)))+(len>24?'…':'');
        } else {
          node.value = toHex(content.subarray(0,Math.min(len,24)))+(len>24?'…':'');
        }
      }
      node.total = pos-start;
      return node;
    }

    try{
      var root=one(0);
      var trailing = b.length-pos;
      return {value:{root:root, consumed:pos, trailing:trailing, warnings:warns}, error:''};
    }catch(e){ return {value:null, error:e.message}; }
  }

  function flatten(node, depth, out){
    out=out||[]; depth=depth||0;
    out.push({depth:depth, node:node});
    for(var i=0;i<node.children.length;i++) flatten(node.children[i], depth+1, out);
    return out;
  }
  function oidList(node, out){
    out=out||[];
    if(node.oid) out.push(node.oid);
    for(var i=0;i<node.children.length;i++) oidList(node.children[i], out);
    return out;
  }

  var API={parse:parse, flatten:flatten, oidList:oidList, decodeOid:decodeOid,
           hexToBytes:hexToBytes, b64ToBytes:b64ToBytes, toHex:toHex, OIDS:OIDS};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__Asn1Forge__=API;
})();
